// P-12: operator records whole-system-residue when the surviving change leaves the software boundary

#[test]
fn operator_records_whole_system_residue_when_change_leaves_software_boundary() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "Ops",
            "--description",
            "on-call load",
            "--positive-state",
            "trained team",
            "--negative-state",
            "queue collapse",
        ],
    );
    let add = run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "support queue overwhelms on-call",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "add auto-retry in service",
            "--whole-system",
            "--notes",
            "policy zig: cap tickets and retrain support before software patch",
        ],
    );
    assert!(
        add.status.success(),
        "add stressor with whole-system failed: {}",
        String::from_utf8_lossy(&add.stderr)
    );
    let residues = std::fs::read_to_string(dir.path().join("residual/residues.csv")).unwrap();
    assert!(
        residues.contains("whole-system-residue"),
        "expected whole-system-residue status in residues.csv, got:\n{residues}"
    );
    assert!(
        residues.contains("whole-system"),
        "expected whole-system component in residues.csv, got:\n{residues}"
    );
    let stressors = std::fs::read_to_string(dir.path().join("residual/stressors.csv")).unwrap();
    assert!(
        stressors.contains("whole-system-residue"),
        "naive_change should accept whole-system-residue, got:\n{stressors}"
    );
}

