use anyhow::{bail, Context, Result};
use std::path::Path;

use crate::storage::format::{read_residues, write_residues};
use crate::structure::analysis::residues::Residue;

pub fn load(residual_dir: &Path) -> Result<Vec<Residue>> {
    read_residues(residual_dir)
}

pub fn append(residual_dir: &Path, residue: Residue) -> Result<()> {
    let existing = load(residual_dir)?;
    let mut all = existing;
    all.push(residue);
    write_residues(residual_dir, &all)?;
    Ok(())
}

pub fn next_id(residues: &[Residue]) -> String {
    let max = residues
        .iter()
        .filter_map(|r| {
            r.id.strip_prefix("R-").and_then(|n| n.parse::<u32>().ok())
        })
        .max()
        .unwrap_or(0);
    format!("R-{max:02}")
}

pub fn force_exists(residual_dir: &Path, force_id: &str) -> Result<bool> {
    let stressors = crate::storage::stressors::load(residual_dir)?;
    if stressors.iter().any(|s| s.id == force_id) {
        return Ok(true);
    }
    let purposes = crate::storage::purposes::load(residual_dir)?;
    if purposes.iter().any(|p| p.id == force_id) {
        return Ok(true);
    }
    let forces = crate::storage::format::read_forces(residual_dir)?;
    Ok(forces.iter().any(|f| f.id == force_id))
}

pub fn append_whole_system(
    residual_dir: &Path,
    force_id: &str,
    notes: &str,
) -> Result<String> {
    if !force_exists(residual_dir, force_id)? {
        bail!("force id '{}' not found in stressors, purposes, or forces", force_id);
    }
    let existing = load(residual_dir)?;
    let id = next_id(&existing);
    let residue = Residue::whole_system(id.clone(), force_id, notes);
    append(residual_dir, residue)?;
    Ok(id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn append_whole_system_writes_residue_row() {
        let dir = tempdir().unwrap();
        crate::storage::stressors::append(
            dir.path(),
            crate::storage::stressors::Stressor {
                id: "S-01".into(),
                description: "d".into(),
                attractor_id: "A-01".into(),
                naive_change: "none".into(),
                outcomes: "".into(),
                components_affected: "".into(),
            },
        )
        .unwrap();
        let id = append_whole_system(dir.path(), "S-01", "hardware zig").unwrap();
        assert_eq!(id, "R-01");
        let loaded = load(dir.path()).unwrap();
        assert_eq!(loaded.len(), 1);
        assert!(loaded[0].is_whole_system());
    }

    #[test]
    fn append_whole_system_rejects_unknown_force() {
        let dir = tempdir().unwrap();
        let err = append_whole_system(dir.path(), "S-99", "notes").unwrap_err();
        assert!(err.to_string().contains("not found"));
    }
}

